import{_ as e,o as p,c as l,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"コアラ家計簿 会員サービス規約","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/legal/membership.md","filePath":"v1/ja/legal/membership.md"}'),i={name:"v1/ja/legal/membership.md"};function t(o,a,h,n,d,s){return p(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="コアラ家計簿-会員サービス規約" tabindex="-1">コアラ家計簿 会員サービス規約 <a class="header-anchor" href="#コアラ家計簿-会員サービス規約" aria-label="Permalink to &quot;コアラ家計簿 会員サービス規約&quot;">​</a></h1><p>更新日：2026年5月3日</p><p>施行日：2026年5月3日</p><p>重要なお知らせ</p><p>お客様の権利を保護するため、「コアラ家計簿 会員サービス」（以下「会員サービス」）の購入、更新または利用を行う前に、本規約を必ずよくお読みいただき、内容を十分にご理解ください。特に、免責・責任制限、自動更新、解約および返金、紛争解決に関する条項にご注意ください。</p><p>【同意】お客様が本規約に同意して会員サービスを購入/更新する、またはその他いかなる方法であれ会員サービスを実際に利用した場合、お客様は本規約の全てを読み、理解し、同意したものとみなされます。本規約は、お客様とコアラ家計簿（Koala）の間で法的拘束力を有します。</p><p>【一般条項】本規約は一般的な雛形であり、適用される法令、プラットフォーム規則（例：Apple App Store）、または機能変更等により更新される場合があります。本規約または将来の更新に同意できない場合は、直ちに会員サービスの購入または利用を中止してください。</p><hr><h2 id="_1-定義および当事者" tabindex="-1">1. 定義および当事者 <a class="header-anchor" href="#_1-定義および当事者" aria-label="Permalink to &quot;1. 定義および当事者&quot;">​</a></h2><p>1.1 「コアラ家計簿」（以下「Koala」または「本アプリ」）とは、個人開発者が運営する記帳アプリおよび関連サービスを指します。</p><p>1.2 「運営者/開発者」とは、本アプリおよび会員サービスを提供・運営する個人開発者（以下「運営者」）を指します。</p><p>1.3 「お客様/ユーザー」とは、本アプリをダウンロード、インストールし、登録/ログインの上、本アプリおよび会員サービスを利用する自然人を指します。</p><p>1.4 「会員」とは、プラットフォームが提供する支払方法により会員サービスを適法に購入し、有効期間中に所定の特典を受けるユーザーを指します。</p><p>1.5 「プラットフォーム」とは、お客様が会員サービスを購入するために利用する第三者の配信・決済プラットフォーム（例：Apple App Store）を指します。課金、返金、領収書等に関する事項は、プラットフォーム規則にも従うものとします。</p><h2 id="_2-適用範囲および変更" tabindex="-1">2. 適用範囲および変更 <a class="header-anchor" href="#_2-適用範囲および変更" aria-label="Permalink to &quot;2. 適用範囲および変更&quot;">​</a></h2><p>2.1 本規約は、お客様による会員サービスの購入および利用に適用されます。本アプリの利用規約およびプライバシーポリシーとあわせて、当事者間の合意体系を構成します。会員サービスに関する事項について本規約と他の規約が矛盾する場合は本規約が優先し、それ以外の事項は関連規約およびプラットフォーム規則に従います。</p><p>2.2 運営者は、法令・監督要件、プラットフォーム規則、運用上の必要等により本規約を更新することがあります。更新後の規約は本アプリ内または関連ページに表示され、公示日から効力を生じます。更新後も会員サービスを利用した場合、お客様は更新後の規約に同意したものとみなされます。同意いただけない場合は会員サービスの利用を中止し、プラットフォーム規則に従ってサブスクリプションを解約してください。</p><h2 id="_3-会員サービスの内容" tabindex="-1">3. 会員サービスの内容 <a class="header-anchor" href="#_3-会員サービスの内容" aria-label="Permalink to &quot;3. 会員サービスの内容&quot;">​</a></h2><p>3.1 会員サービスはデジタルサービスであり、本アプリ内の一部機能を解放または強化します。会員特典は本アプリの「会員/会員を解放」ページの表示に従い、以下を含む場合があります（例示であり、これに限りません）：</p><ul><li>クイック記帳関連機能</li><li>複数帳簿（マルチ台帳）機能</li><li>クラウド同期機能</li><li>複数通貨対応</li><li>エクスポート機能</li><li>分割記帳機能</li><li>精算/立替関連機能</li></ul><p>3.2 会員サービスは、金融・投資・税務・監査・会計等の専門的助言ではありません。統計、レポート、為替換算、エクスポート等はツールとして提供されるものであり、運営者は適合性、完全性、適時性を保証しません。</p><p>3.3 会員特典は、製品のアップデートにより追加・変更・終了、または条件が変更される場合があります。重要な変更がある場合、運営者は合理的な範囲で告知します。お客様は、これらの変更が必ずしも契約違反または返金事由にならないことを理解し同意します。</p><h2 id="_4-購入方法、期間および料金" tabindex="-1">4. 購入方法、期間および料金 <a class="header-anchor" href="#_4-購入方法、期間および料金" aria-label="Permalink to &quot;4. 購入方法、期間および料金&quot;">​</a></h2><p>4.1 お客様は本アプリ内の購入導線から会員サービスを購入できます。月額/年額等のプランが提供される場合があり、購入画面の表示に従います。</p><p>4.2 料金はプラットフォーム上に表示され、実際の課金金額はプラットフォームにより確定します。地域、通貨、税制により価格が異なる場合があります。</p><p>4.3 会員特典は、プラットフォームによる購入成功の確認後に有効となります。有効期間はプラットフォームの注文/サブスクリプション状態に従います。</p><p>4.4 端末変更や再インストールを行った場合でも、同一のプラットフォームアカウントでログインし、プラットフォーム規則を満たす限り、「購入の復元」等により会員特典を復元できる場合があります。</p><h2 id="_5-自動更新-サブスクリプション" tabindex="-1">5. 自動更新（サブスクリプション） <a class="header-anchor" href="#_5-自動更新-サブスクリプション" aria-label="Permalink to &quot;5. 自動更新（サブスクリプション）&quot;">​</a></h2><p>5.1 自動更新型の会員サービスを購入した場合、プラットフォームは各請求期間の終了前に自動的に課金を行い、会員期間を延長します。課金タイミング、課金方法、更新失敗時の取り扱いはプラットフォーム規則に従います。</p><p>5.2 お客様はプラットフォームのサブスクリプション管理画面から自動更新を解約できます。解約後も、既に支払済みの期間満了までは会員特典を利用でき、期間満了後は更新されません。</p><p>5.3 Apple 端末の場合、通常は「設定 → Apple ID → サブスクリプション」から解約できます（システムバージョンにより異なる場合があります）。本アプリ内の「サブスクリプション管理」等の入口は便宜的な遷移であり、プラットフォームの最終処理を変更するものではありません。</p><h2 id="_6-解約および返金" tabindex="-1">6. 解約および返金 <a class="header-anchor" href="#_6-解約および返金" aria-label="Permalink to &quot;6. 解約および返金&quot;">​</a></h2><p>6.1 会員サービスはデジタルコンテンツ/デジタルサービスです。法令に別段の定めがある場合を除き、返金の可否、返金額、処理期間等はプラットフォーム規則により定まります。運営者はプラットフォームを介さずに直接解約・返金を行うことはできません。</p><p>6.2 不審な課金、重複課金、特典の未反映等が疑われる場合、まずプラットフォーム上で注文/サブスクリプション状態をご確認のうえ、プラットフォームの手続に従って返金申請または異議申立てを行ってください。あわせて、第 12 条の連絡先から運営者へご連絡いただければ、調査に協力します。</p><p>6.3 更新前に解約しなかったことによる自動更新課金、誤操作による購入等の結果は、原則としてお客様の責任となります（プラットフォーム規則および適用法令に従います）。</p><h2 id="_7-利用ルールおよび制限" tabindex="-1">7. 利用ルールおよび制限 <a class="header-anchor" href="#_7-利用ルールおよび制限" aria-label="Permalink to &quot;7. 利用ルールおよび制限&quot;">​</a></h2><p>7.1 会員サービスは、お客様本人の合理的な範囲での個人利用に限られます。譲渡、贈与、貸与、転売、または第三者への商業的提供はできません。</p><p>7.2 お客様は、クラッキング、リバースエンジニアリング、改ざん、脆弱性の悪用、自動化スクリプト等の不正手段により会員特典を取得または利用してはなりません。</p><p>7.3 お客様が本規約、適用法令またはプラットフォーム規則に違反した場合、運営者は事前通知なく、機能制限、サービス停止、会員特典の終了等の措置を講じることがあります。これにより生じた損害はお客様が負担します。</p><h2 id="_8-中断、変更および終了" tabindex="-1">8. 中断、変更および終了 <a class="header-anchor" href="#_8-中断、変更および終了" aria-label="Permalink to &quot;8. 中断、変更および終了&quot;">​</a></h2><p>8.1 運営者はサービスの継続性と安定性の確保に努めますが、以下に起因する中断、遅延、障害または一部利用不能について責任を負いません：</p><ul><li>メンテナンス、アップグレード、修理、データセンター/ネットワーク/第三者サービス（クラウド、プッシュ通知、決済プラットフォーム等）の障害</li><li>不可抗力または政府行為</li><li>お客様の端末、OS バージョン、通信環境、権限設定等</li></ul><p>8.2 運営者は、セキュリティ、コンプライアンス、製品方針等の理由により会員サービスを変更または終了することがあります。終了により利用に影響が生じる場合、可能な範囲で合理的に告知します。料金精算や返金は、引き続きプラットフォーム規則および適用法令に従います。</p><h2 id="_9-データおよびクラウド同期に関する特記事項" tabindex="-1">9. データおよびクラウド同期に関する特記事項 <a class="header-anchor" href="#_9-データおよびクラウド同期に関する特記事項" aria-label="Permalink to &quot;9. データおよびクラウド同期に関する特記事項&quot;">​</a></h2><p>9.1 会員特典としてクラウド同期が含まれる場合、第三者サービスおよびネットワーク状況に依存します。運営者は機能の提供に努めますが、リアルタイム性、完全性、無誤差を保証しません。</p><p>9.2 重要なデータは定期的にバックアップすることを推奨します。端末紛失、誤削除、通信障害、同期衝突、第三者サービス障害等によるデータ消失または不整合について、運営者は法令で認められる範囲で責任を負いません。</p><h2 id="_10-知的財産権" tabindex="-1">10. 知的財産権 <a class="header-anchor" href="#_10-知的財産権" aria-label="Permalink to &quot;10. 知的財産権&quot;">​</a></h2><p>10.1 本アプリおよび関連コンテンツ（プログラム、UI、アイコン、商標、テキスト、アルゴリズム、データ構造等）の権利は、運営者または正当な権利者に帰属します。</p><p>10.2 許可なく、複製、改変、配布、賃貸、販売その他侵害行為を行うことはできません。</p><h2 id="_11-免責および責任制限" tabindex="-1">11. 免責および責任制限 <a class="header-anchor" href="#_11-免責および責任制限" aria-label="Permalink to &quot;11. 免責および責任制限&quot;">​</a></h2><p>11.1 法令で認められる最大範囲で、会員サービスの利用または利用不能に起因する間接損害、逸失利益、データ損失等について、運営者は責任を負いません。</p><p>11.2 本規約に基づき運営者が責任を負う場合、その責任総額は、当該紛争に関連する会員サービスについて直近 1 請求期間にお客様が実際に支払った金額を上限とします（適用法令に別段の定めがある場合を除きます）。</p><h2 id="_12-お問い合わせ" tabindex="-1">12. お問い合わせ <a class="header-anchor" href="#_12-お問い合わせ" aria-label="Permalink to &quot;12. お問い合わせ&quot;">​</a></h2><p>会員サービス、サブスクリプション、購入の復元、特典に関する不具合等についてのお問い合わせは、以下までご連絡ください。</p><ul><li>メール：ruanweidev@163.com</li></ul><h2 id="_13-準拠法および紛争解決" tabindex="-1">13. 準拠法および紛争解決 <a class="header-anchor" href="#_13-準拠法および紛争解決" aria-label="Permalink to &quot;13. 準拠法および紛争解決&quot;">​</a></h2><p>13.1 本規約の成立、効力、履行、解釈および紛争解決は、中華人民共和国の法令（抵触法の規定を除く）に準拠します。</p><p>13.2 本規約に起因または関連する紛争は、まず誠実に協議して解決を図ります。協議で解決しない場合、いずれの当事者も運営者所在地の管轄人民法院に提訴できます。</p><h2 id="_14-その他" tabindex="-1">14. その他 <a class="header-anchor" href="#_14-その他" aria-label="Permalink to &quot;14. その他&quot;">​</a></h2><p>14.1 本規約の一部が無効となっても、その他の条項の効力には影響しません。</p><p>14.2 見出しは便宜上のものであり、解釈に影響しません。</p><p>14.3 本規約とプラットフォーム規則が抵触する場合、支払い、更新、返金、サブスクリプション状態の認定等はプラットフォーム規則が優先され、それ以外の事項は本規約が優先されます。</p>',62)])])}const u=e(i,[["render",t]]);export{c as __pageData,u as default};
